#include "animation_morph.h"
#include <algorithm>
#include <cmath>
#include <limits>
#include <stdexcept>
namespace moon {namespace {
MorphBounds bounds(const timeline::Surface& s){if(s.width<1||s.height<1||s.pixels.size()!=std::size_t(s.width)*s.height)throw std::invalid_argument("Invalid morph source surface");int l=s.width,t=s.height,r=-1,b=-1;for(int y=0;y<s.height;++y)for(int x=0;x<s.width;++x)if(s.pixels[std::size_t(y)*s.width+x]>>24){l=std::min(l,x);t=std::min(t,y);r=std::max(r,x);b=std::max(b,y);}if(r<l)throw std::invalid_argument("Morph tween requires content at both endpoints");return {l,t,r-l+1,b-t+1};}
struct DistanceField {std::vector<float> distance;std::vector<int> nearest;};
DistanceField distanceField(const std::vector<timeline::Pixel>& colors,int width,int height,bool inside){DistanceField out;out.distance.assign(colors.size(),std::numeric_limits<float>::infinity());out.nearest.assign(colors.size(),-1);for(std::size_t i=0;i<colors.size();++i)if(bool(colors[i]>>24)==inside){out.distance[i]=0;out.nearest[i]=static_cast<int>(i);}auto visit=[&](int i,int other,double cost){const double candidate=double(out.distance[other])+cost;if(candidate<out.distance[i]){out.distance[i]=static_cast<float>(candidate);out.nearest[i]=out.nearest[other];}};const double diagonal=std::sqrt(2.);for(int y=0;y<height;++y)for(int x=0;x<width;++x){const int i=y*width+x;if(x>0)visit(i,i-1,1);if(y>0){visit(i,i-width,1);if(x>0)visit(i,i-width-1,diagonal);if(x+1<width)visit(i,i-width+1,diagonal);}}for(int y=height-1;y>=0;--y)for(int x=width-1;x>=0;--x){const int i=y*width+x;if(x+1<width)visit(i,i+1,1);if(y+1<height){visit(i,i+width,1);if(x>0)visit(i,i+width-1,diagonal);if(x+1<width)visit(i,i+width+1,diagonal);}}return out;}
MorphShapeField shapeField(const timeline::Surface& source,MorphBounds b,int width,int height){const int stride=width+2;MorphShapeField out;out.colors.resize(std::size_t(stride)*(height+2));for(int y=0;y<height;++y)for(int x=0;x<width;++x){const int sx=b.x+static_cast<int>(std::floor((x+.5)*b.width/width)),sy=b.y+static_cast<int>(std::floor((y+.5)*b.height/height));out.colors[std::size_t(y+1)*stride+x+1]=source.pixels[std::size_t(sy)*source.width+sx];}auto inner=distanceField(out.colors,stride,height+2,true);auto outer=distanceField(out.colors,stride,height+2,false);out.signedDistance=std::move(inner.distance);for(std::size_t i=0;i<out.colors.size();++i){if(out.colors[i]>>24)out.signedDistance[i]=static_cast<float>(.5-double(outer.distance[i]));else{out.signedDistance[i]=static_cast<float>(double(out.signedDistance[i])-.5);out.colors[i]=inner.nearest[i]>=0?out.colors[inner.nearest[i]]:0;}}return out;}
unsigned byte(double x){return static_cast<unsigned>(std::clamp(std::floor(x+.5),0.,255.));}
int rounded(double x){return static_cast<int>(std::floor(x+.5));}
}
MorphTweenPlan prepareMorphTween(const timeline::Surface& start,const timeline::Surface& end){MorphTweenPlan out;out.from=bounds(start);out.to=bounds(end);out.width=std::max(out.from.width,out.to.width);out.height=std::max(out.from.height,out.to.height);if(out.width>16384||out.height>16384||std::uint64_t(out.width+2)*(out.height+2)>1024*1024)throw std::length_error("Morph tween source exceeds shape-field budget");out.a=shapeField(start,out.from,out.width,out.height);out.b=shapeField(end,out.to,out.width,out.height);return out;}
timeline::Surface morphTweenSurface(const MorphTweenPlan& plan,const timeline::Surface& start,const timeline::Surface& end,double progress,std::size_t maxPixels){if(!std::isfinite(progress))throw std::invalid_argument("Invalid morph tween progress");const double t=std::clamp(progress,0.,1.);auto lerp=[&](double a,double b){return a+(b-a)*t;};timeline::Surface out;out.width=std::max(1,rounded(lerp(plan.from.width,plan.to.width)));out.height=std::max(1,rounded(lerp(plan.from.height,plan.to.height)));out.offsetX=rounded(lerp(double(start.offsetX)+plan.from.x,double(end.offsetX)+plan.to.x));out.offsetY=rounded(lerp(double(start.offsetY)+plan.from.y,double(end.offsetY)+plan.to.y));if(std::uint64_t(out.width)*out.height>maxPixels)throw std::length_error("Morph tween exceeds output pixel budget");out.pixels.resize(std::size_t(out.width)*out.height);for(int y=0;y<out.height;++y)for(int x=0;x<out.width;++x){auto& output=out.pixels[std::size_t(y)*out.width+x];if(t==0||t==1){const auto& source=t==0?start:end;const auto& b=t==0?plan.from:plan.to;output=source.pixels[std::size_t(b.y+y)*source.width+b.x+x];continue;}const int sx=static_cast<int>(std::floor((x+.5)*plan.width/out.width)),sy=static_cast<int>(std::floor((y+.5)*plan.height/out.height));const auto i=std::size_t(sy+1)*(plan.width+2)+sx+1;if(lerp(plan.a.signedDistance[i],plan.b.signedDistance[i])>0)continue;const auto a=plan.a.colors[i],b=plan.b.colors[i];for(int shift:{0,8,16,24})output|=timeline::Pixel(byte(lerp((a>>shift)&255,(b>>shift)&255)))<<shift;}return out;}
}
